import { zodResolver } from '@hookform/resolvers/zod';
import { z } from 'zod';
import { useForm } from 'react-hook-form';
import { Button } from '@/components/ui/button';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import Logo from '@/assets/svg/logo';
import LockIcon from '@/components/icons/Lock';
import UserIcon from '@/components/icons/UserIcon';

import { useState } from 'react';
import axios from 'axios';
import { apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { useAppDispatch } from '@/core/global-store';
import { useNavigate } from 'react-router-dom';
import { setCredentials, setMe } from '@/core/global-store/features/auth/authSlice';
import { setSession, unwrapSanctumMeResponse } from '@/features/auth/guard/utils';
import { NewPasswordSchema } from '../schemas/NewPasswordSchema';

export function NewPasswordForm() {
    const dispatch = useAppDispatch();
    const navigate = useNavigate();
    const [errMsg, setErrMsg] = useState('');

    const form = useForm<z.infer<typeof NewPasswordSchema>>({
        resolver: zodResolver(NewPasswordSchema),
        defaultValues: {
            new_password: '',
            confirm_password: '',
        },
    });

    const { formState } = form;

    async function onSubmit(data: z.infer<typeof NewPasswordSchema>) {
        try {
            const response = await apiPost({
                endpoint: endpoints.auth.newPassword,
                body: { new_password: data.new_password, confirm_password: data.confirm_password },
            });

            setErrMsg('');
            const token = response.data.data.token as string;
            const loginUser = response.data.data;
            setSession(token);
            dispatch(setCredentials({ token, user: loginUser }));

            try {
                const meRes = await axios.get(endpoints.auth.me);
                const mePayload = unwrapSanctumMeResponse(meRes.data);
                dispatch(setMe(mePayload));
                if (mePayload) {
                    dispatch(setCredentials({ token, user: mePayload as any }));
                }
            } catch {
                /* keep login user if /me fails */
            }

            navigate('/', { replace: true });
        } catch (err: any) {
            if (!err?.response) {
                setErrMsg('No Server Response');
            } else if (err?.response?.status === 400) {
                setErrMsg('Missing Admin Code or password');
            } else if (err?.response?.status === 401) {
                setErrMsg('wrong Admin Code or password');
            } else {
                setErrMsg('Login failed');
            }
        }
    }

    return (
        <Form {...form}>
            <form
                onSubmit={form.handleSubmit(onSubmit)}
                className="sm:max-w-[450px] w-full mx-auto bg-[#FFFFFF] font-cairo space-y-6 shadow-[0px_8px_13px_-3px_#00000012] p-6 rounded-2xl border border-[#F3E6FF]"
            >
                <div className="flex items-center justify-center">
                    <Logo />
                </div>

                <FormField
                    control={form.control}
                    name="new_password"
                    render={({ field }) => (
                        <FormItem>
                            <FormLabel className="text-[#100147]">كلمة المرور الجديدة</FormLabel>
                            <FormControl>
                                <div className="relative">
                                    <Input type="password" className="px-8" {...field} />
                                    <span className="absolute end-2 top-1/2 -translate-y-1/2 text-[#B8B6C2]">
                                        <UserIcon className="!w-4 !h-4" />
                                    </span>
                                </div>
                            </FormControl>
                            <FormMessage />
                        </FormItem>
                    )}
                />

                <FormField
                    control={form.control}
                    name="confirm_password"
                    render={({ field }) => (
                        <FormItem>
                            <FormLabel className="text-[#100147]">تأكيد كلمة المرور الجديدة</FormLabel>
                            <FormControl>
                                <div className="relative">
                                    <Input type="password" className="px-8" {...field} />
                                    <span className="absolute end-2 top-1/2 -translate-y-1/2 text-[#B8B6C2]">
                                        <LockIcon width="16" height="16" />
                                    </span>
                                </div>
                            </FormControl>
                            <FormMessage />
                        </FormItem>
                    )}
                />

                <div className="text-red-error-600">{errMsg.length > 0 && <p>{errMsg}</p>}</div>
                <Button
                    type="submit"
                    className={`w-full ${formState.isDirty ? 'bg-primery-blue-700 hover:bg-primery-blue-700' : 'bg-primery-blue-200 hover:bg-primery-blue-200'}`}
                >
                    التالي
                </Button>
            </form>
        </Form>
    );
}
