import Bg from '@/assets/imgs/bg.jpg';
import { NewPasswordForm } from '../components/NewPasswordForm';

export default function NewPasswordPage() {
    return (
        <section
            className="flex flex-col items-center justify-between min-h-screen w-full bg-cover bg-center bg-no-repeat"
            style={{ backgroundImage: `url(${Bg})` }}
        >
            <div className="flex items-center justify-between w-full my-auto px-[50px] gap-10">
                <NewPasswordForm />
            </div>
        </section>
    );
}
